def verbs_for(role: str) -> list:
    """Итоги, которые роль вправе сдавать (по RULES): Инженеру и Исследователю не показываем accept/return, Судье — done/pr/continue.
    CEO и роль не из таблицы — все (их сессии не запускает диспетчер)."""
    if role not in ("researcher", "engineer", "judge"):
        return list(RESULTS)
    return [r for r in RESULTS if role in RULES[r][0]]


def proofs_for(role: str) -> str:
    return ", ".join(f"{r} — {PROOF_SHORT[r]}" for r in verbs_for(role) if r in PROOF_SHORT)


def check(role: str, result: str, why: str, pr=None, sha: str = "", path: str = "", form: str = "",
          root: Path = Path("."), owner: str = "", why_owner: str = "") -> str:
    """Пустая строка — команда годна; иначе — что исправить (текст отказа в сессии роли)."""
    if result not in RESULTS:
        return f"неизвестный итог {result!r}; допустимо: {', '.join(RESULTS)}"
    who, need = RULES[result]
    if not role and result == "done":
        role = "ceo"
    formal = role == "judge" and (owner or "").strip() == "judge" and (result == "done" or (result == "accept" and not (pr or sha)))
    if formal:  # TK-225 (В-229 п.4): тикет Судьи закрывается только по артефакту в git, не вручную
        who = who | {"judge"}
    if role not in who:
        return f"итог {result} — не для роли {role or '(не роль)'}; вправе: {', '.join(sorted(who))}"
    why = (why or "").strip()
    if not why:
        return "нужен --why «зачем/почему» (≤ 200 знаков)"
    if result == "ask-owner" and role == "judge" and why_owner not in OWNER_REASONS:
        # V2-1: владельцу — только деньги/направление/необратимое/бизнес-правило; остальное Судья решает сам (blocked, если встал)
        return (f"ask-owner к владельцу — только с --why-owner {'|'.join(OWNER_REASONS)}; другой повод владельцу не "
                f"уходит: реши сам по методике либо blocked")
    if len(why) > WHY_MAX:
        return f"--why длиннее {WHY_MAX} знаков ({len(why)}) — сократи"

    def _exists(p: str) -> bool:
        if not (p or "").strip():
            return False
        try:  # TK-109 п.3: не '.', '/', каталог проекта и не путь вне проекта
            base = root.resolve()
            f = (Path(p) if Path(p).is_absolute() else root / p).resolve()
            return f != base and f.is_file() and f.is_relative_to(base)
        except (OSError, ValueError):
            return False

    if formal:
        _, err = tracked_at_head(root, path)
        return err
    if "|" in need:  # Судья: работа в PR (голова) либо без PR (артефакт проверки)
        pr_form = need.partition("|")[0]
        # PR-форма — с номером PR, либо с одним --sha, когда артефакта --path нет. `--sha` рядом с существующим --path без --pr —
        # приёмка без PR (sha — пометка в журнал): промпт учил `accept --sha`, и в живых прогонах этот отказ был у каждого второго
        # запуска Судьи (docs/bench/2026-10-14.md)
        if pr or (sha and not _exists(path)):
            if result == "accept" and not pr:
                return f"итог accept требует {HINT[need]} (--sha без --pr и без существующего --path не годится)"
            need = pr_form
        elif _exists(path):
            return ""
        else:
            return f"итог {result} требует {HINT[need]}"
    if "pr" in need and not (isinstance(pr, int) and pr > 0):
        return f"итог {result} требует {HINT[need]}"
    if "sha" in need and not _SHA.fullmatch((sha or "").lower()):
        return f"итог {result} требует {HINT[need]}"
    if need == "path" and not _exists(path):
        return f"итог done требует {HINT['path']}"
    if need == "form" and not (form or "").strip():
        return f"итог wait требует {HINT['form']}"
    if need == "form":
        import ticket as T
        if T.parse_wait_for(form.strip()) is None:
            return f"wait: форма не понята. Допустимо: {T.WAIT_FOR_FORMATS}"
    return ""


def tracked_at_head(root: Path, path: str) -> tuple[str, str]:
    """(sha HEAD, "") если path — файл проекта, tracked в git на HEAD и не изменён в рабочем дереве; иначе ("", отказ)."""
    import subprocess
    hint = "итог по тикету Судьи требует --path <файл, закоммиченный в git (tracked на HEAD, без правок в рабочем дереве)>"
    try:
        base = Path(root).resolve()
        f = (Path(path) if Path(path).is_absolute() else base / path).resolve()
        if not (path or "").strip() or f == base or not f.is_file() or not f.is_relative_to(base):
            return "", hint
        rel = f.relative_to(base).as_posix()

        def git(*a):
            return subprocess.run(["git", "-C", str(base), *a], capture_output=True, text=True, timeout=30)
        if git("ls-files", "--error-unmatch", "--", rel).returncode or git("cat-file", "-e", f"HEAD:{rel}").returncode:
            return "", f"{hint}: {rel} не в git на HEAD"
        if git("diff", "--quiet", "HEAD", "--", rel).returncode:
            return "", f"{hint}: {rel} изменён в рабочем дереве — закоммить"
        return git("rev-parse", "--short", "HEAD").stdout.strip(), ""
    except (OSError, ValueError, subprocess.SubprocessError):
        return "", hint


def T_author_is(author: str, role: str) -> bool:
    import ticket as T
    return T.author_is(author, role)


def last_owner_result(tkt) -> str:
    """Последний итог владельца тикета из лога («[итог: X]…»); нет — пусто."""
    for e in reversed(tkt.log):
        m = re.match(r"\[итог: ([\w-]+)\]", e.text.strip())
        if m and T_author_is(e.author, tkt.owner or ""):
            return m.group(1)
    return ""


def continue_streak(tkt, role: str) -> int:
    """Сколько итогов `continue` этой роли подряд в конце лога (запись другого итога обрывает серию)."""
    n = 0
    for e in reversed(tkt.log):
        m = re.match(r"\[итог: ([\w-]+)\]", e.text.strip())
        if not m or not T_author_is(e.author, role):
            continue
        if m.group(1) != "continue":
            break
        n += 1
    return n


def default_reviewer(executor: str = "") -> str:
    """V2-1: Судья проверяет каждый результат — ревьюер по умолчанию; без него только механические задачи Haiku
    (приёмка кодом, не Судьёй)."""
    return "" if (executor or "").strip().lower() == "haiku" else "judge"


def route(role: str, result: str, owner: str, reviewer: str = "", owner_last: str = "", executor: str = "") -> dict:
    """Правки шапки по итогу. accept и wait правит своя команда (accepted / wait_for), здесь — только ход.
    Тикет без ревьюера в шапке (заведён до V2-1): done/pr исполнителя идут Судье, кроме executor: haiku, и
    `reviewer: judge` дописывается в шапку — вся остальная логика диспетчера видит ревьюера."""
    rev = (reviewer or "").strip()
    fill = {}
    if not rev and (default := default_reviewer(executor)):
        rev = fill["reviewer"] = default
    if result == "continue":
        return {"status": "in_progress", "next": role}
    if result == "done":
        if role == "ceo":  # ceo закрывает сам
            return {"status": "done", "next": ""}
        if rev and rev != role and role != "judge":
            return {"status": "in_review", "next": rev, **fill}
        return {"status": "done", "next": ""}
    if result == "pr":
        return {"status": "in_review", "next": rev or "judge", **fill}
    if result == "accept" and owner == "judge" and role == "judge":  # TK-225: тикет Судьи — проверка уже по артефакту
        return {"status": "done", "next": ""}
    if result == "accept":  # без PR; с PR — cmd_accept. Закрываем, только если владелец сдавал done; иначе проверка
        if owner_last == "done":  # шага — владелец продолжает
            return {"status": "done", "next": ""}
        return {"status": "in_progress", "next": owner}
    if result == "return":
        return {"status": "in_progress", "next": owner}
    if result == "blocked":  # TK-094: задача встала → Судье (методика, развилки, гейты); Судья сам встал → владельцу
        return {"status": "blocked", "next": "" if role == "judge" else "judge"}
    if result == "ask-owner":  # TK-218 (В-206): не-Судья → Судье (методика, развилки), без флага; Судья → владельцу
        if role != "judge":    # (вопрос о содержании исследования); строка «ждёт вас», CEO не будится
            return {"status": "blocked", "next": "judge"}
        return {"status": "needs_owner", "next": ""}
    return {}  # wait: статус waiting + wait_for ставит cmd_wait

